function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
// Postgres composite address cast to text looks like ("PO Box 7066",,,,"San Juan",PR,00916-7066,)
// -> split top-level, unquote, drop empty parts, join with commas for a clean address line.
function fmtAddr(raw){
  if(raw==null||raw==='') return '';
  var s=String(raw).trim();
  if(s.charAt(0)==='(' && s.charAt(s.length-1)===')') s=s.slice(1,-1);
  var parts=[],cur='',q=false;
  for(var i=0;i<s.length;i++){var c=s.charAt(i);
    if(c==='"'){ if(q && s.charAt(i+1)==='"'){cur+='"';i++;} else {q=!q;} }
    else if(c===',' && !q){ parts.push(cur); cur=''; }
    else { cur+=c; } }
  parts.push(cur);
  parts=parts.map(function(p){return p.trim();}).filter(function(p){return p!=='';});
  return parts.join(', ');
}
function fld(label,val){var v=(val===''||val==null)?'<span class="na">N/A</span>':esc(val);return '<div class="fld"><span class="lbl">'+esc(label)+'</span><span class="val">'+v+'</span></div>';}
function render(model){
  var h=(model&&model.header)||{};
  var ps=(model&&Array.isArray(model.providers))?model.providers:[];
  var root=document.getElementById('root'); if(!root) return;
  var g=fld('ID',h.id)+fld('Vendor Code',h.code)+fld('Vendor Name',h.pretty_name);
  if(!ps.length){ g+='<div class="sep">Provider mappings</div>'
    +'<div class="fld"><span class="val na">No provider mappings on file for this vendor.</span></div>'; }
  ps.forEach(function(p,i){
    g+='<div class="sep">'+(ps.length>1?('Provider mapping '+(i+1)):'Provider mapping')+(p.provider?(' \u2014 '+esc(p.provider)):'')+'</div>';
    g+=fld('Provider',p.provider)+fld('Provider ID',p.provider_id)+fld('Web',p.web_address)
      +fld('Vendor Name',p.name)+fld('Vendor Code',p.code)+fld('Remittance Name',p.remittance_name)
      +fld('Main Phone',p.main_phone)+fld('Customer Service Phone',p.custsvc_phone)+fld('Remittance Address',fmtAddr(p.remittance_address))
      +fld('Priority Phone',p.priority_phone)+fld('Emergency Phone',p.emergency_phone);
  });
  root.innerHTML = '<div class="title">Vendor Details'+(h.code?(' for '+esc(h.code)):'')+'</div>'
    +'<div class="card"><div class="hd">General Information</div><div class="bd grid">'+g+'</div></div>';
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(render); });

